package keycodec_test

import (
	"errors"
	"testing"

	codec "example.com/keycodec"
)

func TestWireRepresentationIndependent(t *testing.T) {
	k := codec.Key{Region: "us/west", Name: "web blue"}
	got, err := codec.Encode(k)
	if err != nil || got != "us%2Fwest/web%20blue" {
		t.Fatalf("Encode = %q, %v; want fixed wire us%%2Fwest/web%%20blue", got, err)
	}
	decoded, err := codec.Decode("eu%2Fnorth/name%25one")
	if err != nil || decoded != (codec.Key{Region: "eu/north", Name: "name%one"}) {
		t.Fatalf("Decode = %#v, %v; want independently known fields", decoded, err)
	}
	for _, wire := range []string{"", "one", "/two", "one/", "a/b/c", "%/b", "a/%zz"} {
		if _, err := codec.Decode(wire); !errors.Is(err, codec.ErrInvalidKey) {
			t.Errorf("Decode(%q) error = %v; want ErrInvalidKey", wire, err)
		}
	}
	for _, k := range []codec.Key{{Region: "r"}, {Name: "n"}, {}} {
		if _, err := codec.Encode(k); !errors.Is(err, codec.ErrInvalidKey) {
			t.Errorf("Encode(%#v) error = %v; want ErrInvalidKey", k, err)
		}
	}
}

package main

import (
	"bytes"
	"context"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestRejectedBatchProcess(t *testing.T) {
	bin := filepath.Join(t.TempDir(), "ledgerload")
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if out, err := exec.CommandContext(ctx, "go", "build", "-o", bin, ".").CombinedOutput(); err != nil {
		t.Fatalf("build: %v: %s", err, out)
	}
	for _, input := range []string{"first,7\nbad,zero\nlast,9\n", "first,7\nbad,\"unterminated\nlast,9\n"} {
		t.Run(input, func(t *testing.T) {
			dir := t.TempDir()
			cmd := exec.CommandContext(ctx, bin, "--dir", dir)
			cmd.Stdin = strings.NewReader(input)
			var stdout, stderr bytes.Buffer
			cmd.Stdout, cmd.Stderr = &stdout, &stderr
			err := cmd.Run()
			var exit *exec.ExitError
			if !errors.As(err, &exit) || exit.ExitCode() != 2 || stdout.Len() != 0 || stderr.Len() == 0 {
				t.Errorf("process = %v; stdout=%q stderr=%q; want exit2 diagnostic", err, stdout.String(), stderr.String())
			}
			first, err := os.ReadFile(filepath.Join(dir, "first"))
			if err != nil || string(first) != "7\n" {
				t.Errorf("accepted prefix = %q, %v", first, err)
			}
			if _, err := os.Stat(filepath.Join(dir, "last")); !errors.Is(err, os.ErrNotExist) {
				t.Errorf("later record was not absent: %v", err)
			}
		})
	}
	dir := t.TempDir()
	cmd := exec.CommandContext(ctx, bin, "--dir", dir)
	cmd.Stdin = strings.NewReader("web,4\nweb,8\napi,9\n")
	if out, err := cmd.CombinedOutput(); err != nil || len(out) != 0 {
		t.Fatalf("success process: %v, %q", err, out)
	}
	for id, want := range map[string]string{"web": "8\n", "api": "9\n"} {
		got, err := os.ReadFile(filepath.Join(dir, id))
		if err != nil || string(got) != want {
			t.Errorf("%s = %q, %v; want %q", id, got, err, want)
		}
	}
}

package mirror_test

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"reflect"
	"runtime"
	"strings"
	"testing"

	"example.com/mirror"
)

type probeTransport func(*http.Request) (*http.Response, error)

func (f probeTransport) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

func probeClient(body string) *http.Client {
	return &http.Client{Transport: probeTransport(func(r *http.Request) (*http.Response, error) {
		return &http.Response{StatusCode: 200, Body: io.NopCloser(strings.NewReader(body)), Header: make(http.Header)}, nil
	})}
}

func TestFieldValidationAndRetention(t *testing.T) {
	for _, body := range []string{`[{"code":" ","label":"good"}]`, `[{"code":"c","label":"\t"}]`, `[{"code":"c","label":"good"}] {}`, "not JSON"} {
		path := filepath.Join(t.TempDir(), "items.json")
		old := []byte(`[{"code":"old","label":"Retained"}]`)
		if err := os.WriteFile(path, old, 0o644); err != nil {
			t.Fatal(err)
		}
		if err := mirror.Refresh(context.Background(), probeClient(body), "http://example.test/items", path); err == nil {
			t.Errorf("Refresh accepted %q", body)
		}
		got, err := os.ReadFile(path)
		if err != nil || string(got) != string(old) {
			t.Errorf("retained bytes = %q, %v", got, err)
		}
	}
}

func TestCompletePublication(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("pre-opened handle replacement probe specifies Unix semantics")
	}
	path := filepath.Join(t.TempDir(), "items.json")
	old := `[{"code":"old","label":"Retained"}]`
	if err := os.WriteFile(path, []byte(old), 0o644); err != nil {
		t.Fatal(err)
	}
	handle, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer handle.Close()
	body := `[{"code":"new","label":"New label"},{"code":"two","label":"Second"}]`
	if err := mirror.Refresh(context.Background(), probeClient(body), "http://example.test/items", path); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var got []mirror.Item
	if err := json.Unmarshal(data, &got); err != nil {
		t.Fatal(err)
	}
	want := []mirror.Item{{Code: "new", Label: "New label"}, {Code: "two", Label: "Second"}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("published = %#v; want %#v", got, want)
	}
	retained, err := io.ReadAll(handle)
	if err != nil || string(retained) != old {
		t.Errorf("old handle = %q, %v; want unchanged old inode", retained, err)
	}
}

package sweeper_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"example.com/sweeper"
)

func TestHostJoinBeforeRelease(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	started := make(chan struct{})
	cleaning := make(chan struct{})
	permit := make(chan struct{})
	order := make(chan string, 2)
	done := make(chan error, 1)
	defer close(permit)
	go func() {
		done <- sweeper.Run(ctx, time.Millisecond, func(ctx context.Context) error {
			close(started)
			<-ctx.Done()
			close(cleaning)
			select {
			case <-permit:
			case <-time.After(time.Second):
			}
			order <- "callback finished"
			return nil
		}, func() error { order <- "resource released"; return nil })
	}()
	select {
	case <-started:
	case <-time.After(2 * time.Second):
		t.Fatal("callback did not start")
	}
	cancel()
	select {
	case <-cleaning:
	case <-time.After(2 * time.Second):
		t.Fatal("callback did not receive cancellation")
	}
	// Permit cleanup after startup/cancellation observation. Send avoids double-close cleanup.
	permit <- struct{}{}
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("host did not finish")
	}
	var events []string
	for len(events) < 2 {
		select {
		case e := <-order:
			events = append(events, e)
		case <-time.After(2 * time.Second):
			t.Fatal("missing completion/release event")
		}
	}
	if events[0] != "callback finished" || events[1] != "resource released" {
		t.Fatalf("order = %v; host must join before release", events)
	}
}

func TestSuccessfulRecurrence(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	calls := 0
	err := sweeper.Run(ctx, 5*time.Millisecond, func(context.Context) error {
		calls++
		if calls == 2 {
			cancel()
		}
		return nil
	}, func() error { return nil })
	if err != nil || calls != 2 {
		t.Fatalf("Run = %v, successful calls = %d; want 2", err, calls)
	}
}

func TestErrorsAndInvalidInterval(t *testing.T) {
	work, release := errors.New("work"), errors.New("release")
	err := sweeper.Run(context.Background(), time.Second, func(context.Context) error { return work }, func() error { return release })
	if !errors.Is(err, work) || !errors.Is(err, release) {
		t.Errorf("Run lost error identity: %v", err)
	}
	called := false
	err = sweeper.Run(context.Background(), 0, func(context.Context) error { called = true; return nil }, func() error { called = true; return nil })
	if err == nil || called {
		t.Errorf("invalid interval: err=%v called=%v", err, called)
	}
}

